    user_id, admin_id, module, action, method, url, 
    params, result, ip, user_agent, status, error_msg, 
    execution_time, create_time
) VALUES (
    #{userId}, #{adminId}, #{module}, #{action}, #{method}, #{url},
    #{params}, #{result}, #{ip}, #{userAgent}, #{status}, #{errorMsg},
    #{executionTime}, #{createTime}
)

mapper.select:
SELECT * FROM system_log
WHERE 1=1

    AND module LIKE CONCAT('%', #{module}, '%')


    AND action LIKE CONCAT('%', #{action}, '%')


    AND status = #{status}


    AND create_time >= #{startTime}


    AND create_time <= #{endTime}

ORDER BY create_time DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM system_log
WHERE 1=1

    AND module LIKE CONCAT('%', #{module}, '%')


    AND action LIKE CONCAT('%', #{action}, '%')


    AND status = #{status}


    AND create_time >= #{startTime}


    AND create_time <= #{endTime}

SELECT sl.id, sl.admin_id AS adminId, a.name AS adminName, sl.user_id AS userId, u.name AS userName, sl.module, sl.action, sl.method, sl.url, sl.ip, sl.status, sl.execution_time AS executionTime, sl.create_time AS createTime FROM system_log sl LEFT JOIN admin_info a ON sl.admin_id = a.id AND a.is_deleted = 0 LEFT JOIN user_info u ON sl.user_id = u.id AND u.is_deleted = 0
AND sl.module LIKE CONCAT('%', #{query.module}, '%')
AND sl.action LIKE CONCAT('%', #{query.action}, '%')
AND sl.admin_id = #{query.adminId}
AND sl.user_id = #{query.userId}
AND sl.status = #{query.status}
AND sl.create_time >= #{query.startTime}
AND sl.create_time <= #{query.endTime}
ORDER BY sl.id DESC
